  ],
  "verdict": "NEEDS_WORK",
  "checks": [
    {
      "id": "DECISION-JUSTIFIED",
      "result": "PASS",
      "severity": "Minor",
      "finding": "design.md Architecture and normative execution sections justify provider-owned state, separate cloud lifecycle, exact AWS Change Set execution and Azure preview revalidation. ADR 0036 Alternatives explains rejection of a generic engine and prompt-based authorization."
    },
    {
      "id": "OPEN-QUESTIONS-RESOLVABLE",
      "result": "PASS",
      "severity": "Minor",
      "finding": "design.md OQ-001 and OQ-002 identify environment-owner roles and implementation blocking status. Resolution actions are stated in prose: supply live configuration and complete required repository reviews. Advisory: format these actions explicitly as Resolution Path fields."
    },
    {
      "id": "ASSUMPTIONS-VALID",
      "result": "PASS",
      "severity": "Minor",
      "finding": "design.md Assumptions adopts GitHub Actions, matching requirements.md Assumptions. Protected environments and exclusive ownership are explicitly required external configuration, not assumed verified facts; infra-spec.md CI/CD Sequence documents the cross-repository concurrency limitation."
    },
    {
      "id": "NO-REQ-CONTRADICTION",
      "result": "PASS",
      "severity": "Minor",
      "finding": "design.md Constraint Compliance addresses thin integration, ownership, legacy compatibility, write authorization, genuine verification, historical preservation, account/region allowlists, evidence residency/retention and backup/budget prerequisites. Lifecycle and Risks preserve the required timeout and Azure race limitations."
    },
    {
      "id": "PERF-ADDRESSED",
      "result": "PASS",
      "severity": "Minor",
      "finding": "No performance requirements found in requirements.md. infra-spec.md Service Level Objectives nevertheless requires bounded polling deadlines and deterministic termination tests."
    },
    {
      "id": "DEPLOYMENT-CONCRETE",
      "result": "PASS",
      "severity": "Minor",
      "finding": "design.md Deployment / CI Plan specifies packaged plugins, reviewable workflow/IAM templates, credential-free deterministic CI and opt-in protected sandbox jobs. infra-spec.md CI/CD Sequence defines preparation, approval, locking, execution and observation order. No database deployment or incremental feature-flag rollout is proposed."
    },
    {
      "id": "MIGRATION-PLANNED",
      "result": "PASS",
      "severity": "Minor",
      "finding": "design.md Data Plan introduces file-based artifacts and explicit cloud verification version/profile dispatch, retaining unchanged legacy dispatch. It declares no database table or column changes; database migration naming, execution order and volume analysis are therefore inapplicable."
    },
    {
      "id": "INTEGRATION-IDENTIFIED",
      "result": "PASS",
      "severity": "Minor",
      "finding": "design.md External Integration Inventory identifies GitHub approval APIs, ARM, CloudFormation, authoring toolchains, pinned upstream skills and optional managed MCP, with supported contracts and fail-closed unavailable/drift behavior."
    },
    {
      "id": "DESIGN-WITHIN-SCOPE",
      "result": "FAIL",
      "severity": "Major",
      "finding": "design.md Documentation and Release Delivery requires selecting a new semantic version, updating release manifests, creating an annotated tag and publishing it to the configured repository. requirements.md Goals REQ-001–012 and User Stories contain no version/tag publication requirement. The design cites an additional user instruction, but that scope extension is not represented in the governing requirements or acceptance criteria. This leaves downstream implementation and release completion obligations inconsistent with the reviewed requirement baseline. Add the authorized release requirement and acceptance coverage, or remove/defer tag publication from this design."
    },
    {
      "id": "VERIFICATION-PATH-CONCRETE",
      "result": "PASS",
      "severity": "Minor",
      "finding": "design.md Test Strategy and Unit and Integration Boundaries name four deterministic test entry points, TEST-004–010 adversarial authorization/integrity/recovery checks, isolated verify-codex evidence and separately authorized live trials. security-spec.md Security Tests maps the high-risk boundaries to expected denial and evidence outcomes."
    },
    {
      "id": "DOMAIN-CONFORMANCE",
      "result": "SKIP",
      "severity": "Minor",
      "finding": "SKIP: no domain/ directory, as supplied by the host and corroborated by investigation.md. Round 1: no prior-round summary; current summary was not used as substantive review evidence."
    }
  ]
}
